mapper.update:
UPDATE cart
SET status = 0,
    quantity = 0,
    update_time = NOW()
WHERE product_id = #{id}
  AND username = #{userName}

mapper.select:
SELECT c.username, c.product_id AS productId, c.quantity, c.status,
p.image AS productImage, p.price AS price, p.name AS productName, p.price * c.quantity AS totalPrice
FROM cart c INNER JOIN product p ON c.product_id = p.id WHERE c.username = #{userName}
